// Load (RFC 8583 §7.1)
//
// Load ::= < AVP Header: 650 >
//
//	[ Load-Type ]
//	[ Load-Value ]
//	[ SourceID ]
//	*[ AVP ]
type Load struct {
	LoadType  diam.Opt[LoadType] // [ ] LOAD_TYPE code 651
	LoadValue diam.Opt[uint64]   // [ ] LOAD_VALUE code 652
	Sourceid  diam.Opt[string]   // [ ] SOURCEID code 649

	// Unknown holds AVPs not described above. They are re-encoded verbatim.
	Unknown []diam.RawAVP

	seen      uint64 // required AVPs found by DecodeAVPs
	decodeErr error  // first AVP whose value could not be decoded
	excess    error  // first occurrence beyond the grammar maximum
	decoded   bool   // set by DecodeAVPs; required presence is checked only then
}

// AppendAVPs appends the AVPs of m: fixed-position AVPs, the others in
// grammar order, then Unknown. Required AVPs are always written.
func (m *Load) AppendAVPs(b []byte) []byte {
	var s int
	if m.LoadType.Set {
		b, s = diam.BeginAVP(b, 651, 0, 0)
		b = diam.AppendInteger32(b, int32(m.LoadType.V))
		b = diam.EndAVP(b, s)
	}
	if m.LoadValue.Set {
		b, s = diam.BeginAVP(b, 652, 0, 0)
		b = diam.AppendUnsigned64(b, m.LoadValue.V)
		b = diam.EndAVP(b, s)
	}
	if m.Sourceid.Set {
		b, s = diam.BeginAVP(b, 649, 0, 0)
		b = append(b, m.Sourceid.V...)
		b = diam.EndAVP(b, s)
	}
	for _, a := range m.Unknown {
		b = diam.AppendRaw(b, a)
	}
	return b
}

// DecodeAVPs replaces the AVPs of m with those of an AVP sequence.
// It fails only when the sequence
// itself cannot be split into AVPs. AVPs that the grammar does not describe
// go to Unknown; a value that cannot be decoded and an occurrence beyond a
// maximum are skipped and reported by Validate.
func (m *Load) DecodeAVPs(data []byte) error {
	*m = Load{}
	m.decoded = true
	for len(data) > 0 {
		a, rest, err := diam.NextAVP(data)
		if err != nil {
			return err
		}
		data = rest
		// A V-bit with Vendor-Id 0 is not the IETF AVP of that code.
		if a.Vendor == 0 && a.Flags&diam.AVPFlagVendor != 0 {
			m.Unknown = append(m.Unknown, diam.Clone(a))
			continue
		}
		switch uint64(a.Vendor)<<32 | uint64(a.Code) {
		case 651: // LOAD_TYPE code 651
			if m.LoadType.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "LOAD_TYPE")
				}
				continue
			}
			v, err := diam.Integer32(a)
			if err != nil {
				if m.decodeErr == nil {
					m.decodeErr = err
				}
				continue
			}
			m.LoadType = diam.Some(LoadType(v))
		case 652: // LOAD_VALUE code 652
			if m.LoadValue.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "LOAD_VALUE")
				}
				continue
			}
			v, err := diam.Unsigned64(a)
			if err != nil {
				if m.decodeErr == nil {
					m.decodeErr = err
				}
				continue
			}
			m.LoadValue = diam.Some(v)
		case 649: // SOURCEID code 649
			if m.Sourceid.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "SOURCEID")
				}
				continue
			}
			m.Sourceid = diam.Some(string(a.Data))
		default:
			m.Unknown = append(m.Unknown, diam.Clone(a))
		}
	}
	return nil
}

// Validate checks m against its grammar and returns the first violation
// as a *diam.AVPError. Required presence is checked on decoded messages
// only: a zero value is a valid encoding, so a hand-built message has
// nothing to check.
func (m *Load) Validate() error {
	if m.decodeErr != nil {
		return m.decodeErr
	}
	if m.excess != nil {
		return m.excess
	}
	return diam.CheckUnknown(m.Unknown)
}

