//	[ DRMP ]
//	[ Result-Code ]
//	[ Experimental-Result ]
//	{ Auth-Session-State }
//	{ Origin-Host }
//	{ Origin-Realm }
//	[ OC-Supported-Features ]
//	[ OC-OLR ]
//	*[ Load ]
//	*[ Supported-Features ]
//	[ NIDD-Authorization-Response ]
//	*[ Group-User-Identifier ]
//	[ NIA-Flags ]
//	[ Failed-AVP ]
//	*[ Proxy-Info ]
//	*[ Route-Record ]
//	*[AVP]
//
// [ Vendor-Specific-Application-Id ] follows DRMP (§8.2.2 NOTE).
type NiddInformationAnswer struct {
	Header diam.Header

	SessionId                   string                            // < > SESSION_ID code 263
	Drmp                        diam.Opt[Drmp]                    // [ ] DRMP code 301
	VendorSpecificApplicationId *base.VendorSpecificApplicationId // [ ] VENDOR_SPECIFIC_APPLICATION_ID code 260
	ResultCode                  diam.Opt[uint32]                  // [ ] RESULT_CODE code 268
	ExperimentalResult          *base.ExperimentalResult          // [ ] EXPERIMENTAL_RESULT code 297
	AuthSessionState            base.AuthSessionState             // { } AUTH_SESSION_STATE code 277
	OriginHost                  string                            // { } ORIGIN_HOST code 264
	OriginRealm                 string                            // { } ORIGIN_REALM code 296
	OcSupportedFeatures         *OcSupportedFeatures              // [ ] OC_SUPPORTED_FEATURES code 621
	OcOlr                       *OcOlr                            // [ ] OC_OLR code 623
	Load                        []Load                            // *[ ] LOAD code 650
	SupportedFeatures           []SupportedFeatures               // *[ ] SUPPORTED_FEATURES code 628 vendor 10415
	NiddAuthorizationResponse   *NiddAuthorizationResponse        // [ ] NIDD_AUTHORIZATION_RESPONSE code 3151 vendor 10415
	GroupUserIdentifier         []GroupUserIdentifier             // *[ ] GROUP_USER_IDENTIFIER code 3177 vendor 10415
	NiaFlags                    diam.Opt[uint32]                  // [ ] NIA_FLAGS code 3176 vendor 10415
	FailedAvp                   *base.FailedAvp                   // [ ] FAILED_AVP code 279
	ProxyInfo                   []base.ProxyInfo                  // *[ ] PROXY_INFO code 284
	RouteRecord                 []string                          // *[ ] ROUTE_RECORD code 282

	// Unknown holds AVPs not described above. They are re-encoded verbatim.
	Unknown []diam.RawAVP

	seen      uint64 // required AVPs found by DecodeAVPs
	decodeErr error  // first AVP whose value could not be decoded
	excess    error  // first occurrence beyond the grammar maximum
	misplaced error  // first fixed-position AVP found elsewhere
	decoded   bool   // set by DecodeAVPs; required presence is checked only then
}

// AppendAVPs appends the AVPs of m: fixed-position AVPs, the others in
// grammar order, then Unknown. Required AVPs are always written.
func (m *NiddInformationAnswer) AppendAVPs(b []byte) []byte {
	var s int
	b, s = diam.BeginAVP(b, 263, diam.AVPFlagMandatory, 0)
	b = append(b, m.SessionId...)
	b = diam.EndAVP(b, s)
	if m.Drmp.Set {
		b, s = diam.BeginAVP(b, 301, 0, 0)
		b = diam.AppendInteger32(b, int32(m.Drmp.V))
		b = diam.EndAVP(b, s)
	}
	if m.VendorSpecificApplicationId != nil {
		b, s = diam.BeginAVP(b, 260, diam.AVPFlagMandatory, 0)
		b = m.VendorSpecificApplicationId.AppendAVPs(b)
		b = diam.EndAVP(b, s)
	}
	if m.ResultCode.Set {
		b, s = diam.BeginAVP(b, 268, diam.AVPFlagMandatory, 0)
		b = diam.AppendUnsigned32(b, m.ResultCode.V)
		b = diam.EndAVP(b, s)
	}
	if m.ExperimentalResult != nil {
		b, s = diam.BeginAVP(b, 297, diam.AVPFlagMandatory, 0)
		b = m.ExperimentalResult.AppendAVPs(b)
		b = diam.EndAVP(b, s)
	}
	b, s = diam.BeginAVP(b, 277, diam.AVPFlagMandatory, 0)
	b = diam.AppendInteger32(b, int32(m.AuthSessionState))
	b = diam.EndAVP(b, s)
	b, s = diam.BeginAVP(b, 264, diam.AVPFlagMandatory, 0)
	b = append(b, m.OriginHost...)
	b = diam.EndAVP(b, s)
	b, s = diam.BeginAVP(b, 296, diam.AVPFlagMandatory, 0)
	b = append(b, m.OriginRealm...)
	b = diam.EndAVP(b, s)
	if m.OcSupportedFeatures != nil {
		b, s = diam.BeginAVP(b, 621, 0, 0)
		b = m.OcSupportedFeatures.AppendAVPs(b)
		b = diam.EndAVP(b, s)
	}
	if m.OcOlr != nil {
		b, s = diam.BeginAVP(b, 623, 0, 0)
		b = m.OcOlr.AppendAVPs(b)
		b = diam.EndAVP(b, s)
	}
	for i := range m.Load {
		b, s = diam.BeginAVP(b, 650, 0, 0)
		b = (&m.Load[i]).AppendAVPs(b)
		b = diam.EndAVP(b, s)
	}
	for i := range m.SupportedFeatures {
		b, s = diam.BeginAVP(b, 628, 0, 10415)
		b = (&m.SupportedFeatures[i]).AppendAVPs(b)
		b = diam.EndAVP(b, s)
	}
	if m.NiddAuthorizationResponse != nil {
		b, s = diam.BeginAVP(b, 3151, diam.AVPFlagMandatory, 10415)
		b = m.NiddAuthorizationResponse.AppendAVPs(b)
		b = diam.EndAVP(b, s)
	}
	for i := range m.GroupUserIdentifier {
		b, s = diam.BeginAVP(b, 3177, 0, 10415)
		b = (&m.GroupUserIdentifier[i]).AppendAVPs(b)
		b = diam.EndAVP(b, s)
	}
	if m.NiaFlags.Set {
		b, s = diam.BeginAVP(b, 3176, 0, 10415)
		b = diam.AppendUnsigned32(b, m.NiaFlags.V)
		b = diam.EndAVP(b, s)
	}
	if m.FailedAvp != nil {
		b, s = diam.BeginAVP(b, 279, diam.AVPFlagMandatory, 0)
		b = m.FailedAvp.AppendAVPs(b)
		b = diam.EndAVP(b, s)
	}
	for i := range m.ProxyInfo {
		b, s = diam.BeginAVP(b, 284, diam.AVPFlagMandatory, 0)
		b = (&m.ProxyInfo[i]).AppendAVPs(b)
		b = diam.EndAVP(b, s)
	}
	for i := range m.RouteRecord {
		b, s = diam.BeginAVP(b, 282, diam.AVPFlagMandatory, 0)
		b = append(b, m.RouteRecord[i]...)
		b = diam.EndAVP(b, s)
	}
	for _, a := range m.Unknown {
		b = diam.AppendRaw(b, a)
	}
	return b
}

// DecodeAVPs replaces the AVPs of m with those of an AVP sequence; the
// Header is kept.
// It fails only when the sequence
// itself cannot be split into AVPs. AVPs that the grammar does not describe
// go to Unknown; a value that cannot be decoded and an occurrence beyond a
// maximum are skipped and reported by Validate.
func (m *NiddInformationAnswer) DecodeAVPs(data []byte) error {
	*m = NiddInformationAnswer{Header: m.Header}
	m.decoded = true
	idx := -1
	for len(data) > 0 {
		a, rest, err := diam.NextAVP(data)
		if err != nil {
			return err
		}
		data = rest
		idx++
		// A V-bit with Vendor-Id 0 is not the IETF AVP of that code.
		if a.Vendor == 0 && a.Flags&diam.AVPFlagVendor != 0 {
			m.Unknown = append(m.Unknown, diam.Clone(a))
			continue
		}
		switch uint64(a.Vendor)<<32 | uint64(a.Code) {
		case 263: // SESSION_ID code 263
			if m.seen&(uint64(1)<<0) != 0 {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "SESSION_ID")
				}
				continue
			}
			if idx != 0 && m.misplaced == nil {
				m.misplaced = diam.Misplaced(diam.Clone(a), "SESSION_ID")
			}
			m.seen |= uint64(1) << 0
			m.SessionId = string(a.Data)
		case 301: // DRMP code 301
			if m.Drmp.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "DRMP")
				}
				continue
			}
			v, err := diam.Integer32(a)
			if err != nil {
				if m.decodeErr == nil {
					m.decodeErr = err
				}
				continue
			}
			m.Drmp = diam.Some(Drmp(v))
		case 260: // VENDOR_SPECIFIC_APPLICATION_ID code 260
			if m.VendorSpecificApplicationId != nil {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "VENDOR_SPECIFIC_APPLICATION_ID")
				}
				continue
			}
			var v base.VendorSpecificApplicationId
			if err := v.DecodeAVPs(a.Data); err != nil {
				if m.decodeErr == nil {
					m.decodeErr = &diam.AVPError{ResultCode: diam.ResultInvalidAVPLength, AVP: diam.Clone(a), Msg: "malformed grouped AVP VENDOR_SPECIFIC_APPLICATION_ID"}
				}
				continue
			}
			m.VendorSpecificApplicationId = &v
		case 268: // RESULT_CODE code 268
			if m.ResultCode.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "RESULT_CODE")
				}
				continue
			}
			v, err := diam.Unsigned32(a)
			if err != nil {
				if m.decodeErr == nil {
					m.decodeErr = err
				}
				continue
			}
			m.ResultCode = diam.Some(v)
		case 297: // EXPERIMENTAL_RESULT code 297
			if m.ExperimentalResult != nil {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "EXPERIMENTAL_RESULT")
				}
				continue
			}
			var v base.ExperimentalResult
			if err := v.DecodeAVPs(a.Data); err != nil {
				if m.decodeErr == nil {
					m.decodeErr = &diam.AVPError{ResultCode: diam.ResultInvalidAVPLength, AVP: diam.Clone(a), Msg: "malformed grouped AVP EXPERIMENTAL_RESULT"}
				}
				continue
			}
			m.ExperimentalResult = &v
		case 277: // AUTH_SESSION_STATE code 277
			if m.seen&(uint64(1)<<1) != 0 {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "AUTH_SESSION_STATE")
				}
				continue
			}
			v, err := diam.Integer32(a)
			if err != nil {
				if m.decodeErr == nil {
					m.decodeErr = err
				}
				continue
			}
			m.seen |= uint64(1) << 1
			m.AuthSessionState = base.AuthSessionState(v)
		case 264: // ORIGIN_HOST code 264
			if m.seen&(uint64(1)<<2) != 0 {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "ORIGIN_HOST")
				}
				continue
			}
			m.seen |= uint64(1) << 2
			m.OriginHost = string(a.Data)
		case 296: // ORIGIN_REALM code 296
			if m.seen&(uint64(1)<<3) != 0 {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "ORIGIN_REALM")
				}
				continue
			}
			m.seen |= uint64(1) << 3
			m.OriginRealm = string(a.Data)
		case 621: // OC_SUPPORTED_FEATURES code 621
			if m.OcSupportedFeatures != nil {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "OC_SUPPORTED_FEATURES")
				}
				continue
			}
			var v OcSupportedFeatures
			if err := v.DecodeAVPs(a.Data); err != nil {
				if m.decodeErr == nil {
					m.decodeErr = &diam.AVPError{ResultCode: diam.ResultInvalidAVPLength, AVP: diam.Clone(a), Msg: "malformed grouped AVP OC_SUPPORTED_FEATURES"}
				}
				continue
			}
			m.OcSupportedFeatures = &v
		case 623: // OC_OLR code 623
			if m.OcOlr != nil {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "OC_OLR")
				}
				continue
			}
			var v OcOlr
			if err := v.DecodeAVPs(a.Data); err != nil {
				if m.decodeErr == nil {
					m.decodeErr = &diam.AVPError{ResultCode: diam.ResultInvalidAVPLength, AVP: diam.Clone(a), Msg: "malformed grouped AVP OC_OLR"}
				}
				continue
			}
			m.OcOlr = &v
		case 650: // LOAD code 650
			var v Load
			if err := v.DecodeAVPs(a.Data); err != nil {
				if m.decodeErr == nil {
					m.decodeErr = &diam.AVPError{ResultCode: diam.ResultInvalidAVPLength, AVP: diam.Clone(a), Msg: "malformed grouped AVP LOAD"}
				}
				continue
			}
			m.Load = append(m.Load, v)
		case 44732084388468: // SUPPORTED_FEATURES code 628 vendor 10415
			var v SupportedFeatures
			if err := v.DecodeAVPs(a.Data); err != nil {
				if m.decodeErr == nil {
					m.decodeErr = &diam.AVPError{ResultCode: diam.ResultInvalidAVPLength, AVP: diam.Clone(a), Msg: "malformed grouped AVP SUPPORTED_FEATURES"}
				}
				continue
			}
			m.SupportedFeatures = append(m.SupportedFeatures, v)
		case 44732084390991: // NIDD_AUTHORIZATION_RESPONSE code 3151 vendor 10415
			if m.NiddAuthorizationResponse != nil {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "NIDD_AUTHORIZATION_RESPONSE")
				}
				continue
			}
			var v NiddAuthorizationResponse
			if err := v.DecodeAVPs(a.Data); err != nil {
				if m.decodeErr == nil {
					m.decodeErr = &diam.AVPError{ResultCode: diam.ResultInvalidAVPLength, AVP: diam.Clone(a), Msg: "malformed grouped AVP NIDD_AUTHORIZATION_RESPONSE"}
				}
				continue
			}
			m.NiddAuthorizationResponse = &v
		case 44732084391017: // GROUP_USER_IDENTIFIER code 3177 vendor 10415
			var v GroupUserIdentifier
			if err := v.DecodeAVPs(a.Data); err != nil {
				if m.decodeErr == nil {
					m.decodeErr = &diam.AVPError{ResultCode: diam.ResultInvalidAVPLength, AVP: diam.Clone(a), Msg: "malformed grouped AVP GROUP_USER_IDENTIFIER"}
				}
				continue
			}
			m.GroupUserIdentifier = append(m.GroupUserIdentifier, v)
		case 44732084391016: // NIA_FLAGS code 3176 vendor 10415
			if m.NiaFlags.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "NIA_FLAGS")
				}
				continue
			}
			v, err := diam.Unsigned32(a)
			if err != nil {
				if m.decodeErr == nil {
					m.decodeErr = err
				}
				continue
			}
			m.NiaFlags = diam.Some(v)
		case 279: // FAILED_AVP code 279
			if m.FailedAvp != nil {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "FAILED_AVP")
				}
				continue
			}
			var v base.FailedAvp
			if err := v.DecodeAVPs(a.Data); err != nil {
				if m.decodeErr == nil {
					m.decodeErr = &diam.AVPError{ResultCode: diam.ResultInvalidAVPLength, AVP: diam.Clone(a), Msg: "malformed grouped AVP FAILED_AVP"}
				}
				continue
			}
			m.FailedAvp = &v
		case 284: // PROXY_INFO code 284
			var v base.ProxyInfo
			if err := v.DecodeAVPs(a.Data); err != nil {
				if m.decodeErr == nil {
					m.decodeErr = &diam.AVPError{ResultCode: diam.ResultInvalidAVPLength, AVP: diam.Clone(a), Msg: "malformed grouped AVP PROXY_INFO"}
				}
				continue
			}
			m.ProxyInfo = append(m.ProxyInfo, v)
		case 282: // ROUTE_RECORD code 282
			m.RouteRecord = append(m.RouteRecord, string(a.Data))
		default:
			m.Unknown = append(m.Unknown, diam.Clone(a))
		}
	}
	return nil
}

// Validate checks m against its grammar and returns the first violation
// as a *diam.AVPError. Required presence is checked on decoded messages
// only: a zero value is a valid encoding, so a hand-built message has
// nothing to check.
func (m *NiddInformationAnswer) Validate() error {
	if m.decodeErr != nil {
		return m.decodeErr
	}
	if m.excess != nil {
		return m.excess
	}
	if m.decoded && m.seen&(uint64(1)<<0) == 0 {
		return diam.Missing(263, 0, "SESSION_ID")
	}
	if m.decoded && m.seen&(uint64(1)<<1) == 0 {
		return diam.Missing(277, 0, "AUTH_SESSION_STATE")
	}
	if m.decoded && m.seen&(uint64(1)<<2) == 0 {
		return diam.Missing(264, 0, "ORIGIN_HOST")
	}
	if m.decoded && m.seen&(uint64(1)<<3) == 0 {
		return diam.Missing(296, 0, "ORIGIN_REALM")
	}
	if m.misplaced != nil {
		return m.misplaced
	}
	if m.VendorSpecificApplicationId != nil {
		if err := m.VendorSpecificApplicationId.Validate(); err != nil {
			return diam.InGroup(err, 260)
		}
	}
	if m.ExperimentalResult != nil {
		if err := m.ExperimentalResult.Validate(); err != nil {
			return diam.InGroup(err, 297)
		}
	}
	if m.OcSupportedFeatures != nil {
		if err := m.OcSupportedFeatures.Validate(); err != nil {
			return diam.InGroup(err, 621)
		}
	}
	if m.OcOlr != nil {
		if err := m.OcOlr.Validate(); err != nil {
			return diam.InGroup(err, 623)
		}
	}
	for i := range m.Load {
		if err := m.Load[i].Validate(); err != nil {
			return diam.InGroup(err, 650)
		}
	}
	for i := range m.SupportedFeatures {
		if err := m.SupportedFeatures[i].Validate(); err != nil {
			return diam.InGroup(err, 628)
		}
	}
	if m.NiddAuthorizationResponse != nil {
		if err := m.NiddAuthorizationResponse.Validate(); err != nil {
			return diam.InGroup(err, 3151)
		}
	}
	for i := range m.GroupUserIdentifier {
		if err := m.GroupUserIdentifier[i].Validate(); err != nil {
			return diam.InGroup(err, 3177)
		}
	}
	if m.FailedAvp != nil {
		if err := m.FailedAvp.Validate(); err != nil {
			return diam.InGroup(err, 279)
		}
	}
	for i := range m.ProxyInfo {
		if err := m.ProxyInfo[i].Validate(); err != nil {
			return diam.InGroup(err, 284)
		}
	}
	return diam.CheckUnknown(m.Unknown)
}

// DiamHeader implements diam.Message.
func (m *NiddInformationAnswer) DiamHeader() *diam.Header { return &m.Header }

// AppendMarshal appends the encoded message to b. The command code, the
// application id and the R and P bits come from the grammar; the E and T
// bits and the identifiers come from m.Header, which is not modified.
func (m *NiddInformationAnswer) AppendMarshal(b []byte) ([]byte, error) {
	h := m.Header
	h.CommandCode, h.AppID = 8388726, 16777345
	h.Flags = h.Flags&^(diam.FlagRequest|diam.FlagProxiable) | diam.FlagProxiable
	start := len(b)
	b = diam.AppendHeader(b, &h)
	b = m.AppendAVPs(b)
	return diam.FinishMessage(b, start)
}

// Marshal encodes the message.
func (m *NiddInformationAnswer) Marshal() ([]byte, error) { return m.AppendMarshal(nil) }

// Unmarshal decodes a whole message into m, replacing its contents. It
// fails only when the message cannot be framed; grammar violations are
// reported by Validate.
func (m *NiddInformationAnswer) Unmarshal(b []byte) error {
	h, avps, err := diam.ParseHeader(b)
	if err != nil {
		return err
	}
	m.Header = h
	return m.DecodeAVPs(avps)
}

// NewConfigurationInformationAnswerFor returns the answer to req: the request's header
// identifiers with the R and T bits cleared, and its Session-Id.
// Every other AVP is left for the caller to set.
func NewConfigurationInformationAnswerFor(req *ConfigurationInformationRequest) *ConfigurationInformationAnswer {
	ans := &ConfigurationInformationAnswer{Header: diam.AnswerHeader(&req.Header)}
	ans.SessionId = req.SessionId
	return ans
}

// NewReportingInformationAnswerFor returns the answer to req: the request's header
// identifiers with the R and T bits cleared, and its Session-Id.
// Every other AVP is left for the caller to set.
func NewReportingInformationAnswerFor(req *ReportingInformationRequest) *ReportingInformationAnswer {
	ans := &ReportingInformationAnswer{Header: diam.AnswerHeader(&req.Header)}
	ans.SessionId = req.SessionId
	return ans
}

// NewNiddInformationAnswerFor returns the answer to req: the request's header
// identifiers with the R and T bits cleared, and its Session-Id.
// Every other AVP is left for the caller to set.
func NewNiddInformationAnswerFor(req *NiddInformationRequest) *NiddInformationAnswer {
	ans := &NiddInformationAnswer{Header: diam.AnswerHeader(&req.Header)}
	ans.SessionId = req.SessionId
	return ans
}

func init() {
	diam.Register(16777345, 8388718, true, func() diam.Message { return new(ConfigurationInformationRequest) })
	diam.Register(16777345, 8388718, false, func() diam.Message { return new(ConfigurationInformationAnswer) })
	diam.Register(16777345, 8388719, true, func() diam.Message { return new(ReportingInformationRequest) })
	diam.Register(16777345, 8388719, false, func() diam.Message { return new(ReportingInformationAnswer) })
	diam.Register(16777345, 8388726, true, func() diam.Message { return new(NiddInformationRequest) })
	diam.Register(16777345, 8388726, false, func() diam.Message { return new(NiddInformationAnswer) })
}
